// Anello 1 of `npm run verify`: the vendored bek-ts snapshot
// (vendor/bek-ts/src/*) is not silently stale.
//
//  1. Always: every vendored file's sha256 matches vendor/bek-ts/manifest.json
//     (regenerated by scripts/sync-codec.sh). Catches hand-edited vendor
//     files, or sync-codec.sh being run without re-committing the manifest.
//  2. Only when ../bek-ts is reachable (local dev; CI never has it): every
//     vendored file's sha256 also matches the live ../bek-ts/src/<file> it
//     was copied from. Catches bek-ts changing without this repo re-syncing.
import { readFileSync, existsSync } from 'node:fs';
import { createHash } from 'node:crypto';

const sha256 = (path) => createHash('sha256').update(readFileSync(path)).digest('hex');

const manifest = JSON.parse(readFileSync('vendor/bek-ts/manifest.json', 'utf8'));
const files = Object.keys(manifest.files);

let ok = true;

for (const f of files) {
  const path = `vendor/bek-ts/src/${f}`;
  const actual = sha256(path);
  const expected = manifest.files[f];
  if (actual !== expected) {
    console.log(`FAIL: ${path} does not match manifest (expected ${expected}, got ${actual}) -- re-run scripts/sync-codec.sh`);
    ok = false;
  }
}
if (ok) console.log(`PASS: all ${files.length} vendored files match vendor/bek-ts/manifest.json`);

const upstreamSrc = '../bek-ts/src';
if (!existsSync(upstreamSrc)) {
  console.log(`SKIP: upstream drift check -- ${upstreamSrc} not found (sibling checkout needed; expected in CI)`);
} else {
  let drift = false;
  for (const f of files) {
    const vendored = sha256(`vendor/bek-ts/src/${f}`);
    const upstream = sha256(`${upstreamSrc}/${f}`);
    if (vendored !== upstream) {
      console.log(`FAIL: vendor/bek-ts/src/${f} differs from ${upstreamSrc}/${f} -- run scripts/sync-codec.sh`);
      drift = true;
    }
  }
  if (!drift) console.log(`PASS: all ${files.length} vendored files match ${upstreamSrc}`);
  ok = ok && !drift;
}

process.exitCode = ok ? 0 : 1;
